script:
(function () {
  'use strict';
  // Buyer closing costs and cash to close.
  //   Loan = price - down payment. Each fee is a dollar amount or a % of its base: lender fees and
  //   points use the loan amount; title insurance, transfer taxes and property tax use the price.
  //   Closing costs = lender fees + title/settlement + government fees + other services.
  //   Prepaids = prepaid interest (loan x rate / 365 x days) + homeowners insurance paid ahead
  //     (annual premium x months / 12); escrow deposit = monthly tax x months + monthly insurance x months.
  //   Cash to close = down payment + closing costs + prepaids and escrow - earnest money
  //     - seller credits - lender credits; credits only offset costs, so they are capped at
  //     closing costs + prepaids and escrow.
  //   No state transfer-tax tables: the user enters the rate or amount for their area.
  // Verified (Node, scratchpad tests/w3b2e) by hand-adding the defaults: $400,000 price, 20% down ->
  //   loan $320,000; lender fees $3,200 (1%) + $500 + $600 + $50 = $4,350; title $2,000 (0.5% of
  //   price) + $1,000 + $250 = $3,250; recording $150; inspection $450; closing costs $8,200;
  //   prepaid interest $320,000 x 6.5% / 365 x 15 = $854.79; insurance 12 months $1,800; escrow
  //   tax $4,400 / 12 x 3 = $1,100 + insurance $150 x 2 = $300; prepaids and escrow $4,054.79; cash
  //   to close $80,000 + $8,200 + $4,054.79 - $5,000 earnest = $87,254.79. P&I $2,022.62 ($320,000,
  //   6.5%, 30 yrs) + $366.67 tax + $150 insurance = $2,539.28/month (unrounded sum). Credits above
  //   costs are capped ($50,000 seller credit -> $12,254.79 counted).
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 1, maximumFractionDigits: 2 });

  // [input id, label, group, base for %] - base: 'loan' or 'price'; no unit select when null.
  var ITEMS = [
    ['hcOrigination', 'Origination fee', 'lender', 'loan'],
    ['hcPoints', 'Discount points', 'lender', 'loan'],
    ['hcUnderwriting', 'Application and underwriting', 'lender', null],
    ['hcAppraisal', 'Appraisal', 'lender', null],
    ['hcCredit', 'Credit report', 'lender', null],
    ['hcLenderOther', 'Other lender fees', 'lender', null],
    ['hcTitleIns', 'Title insurance', 'title', 'price'],
    ['hcSettlement', 'Settlement or escrow fee', 'title', null],
    ['hcTitleSearch', 'Title search and exam', 'title', null],
    ['hcAttorney', 'Attorney fee', 'title', null],
    ['hcRecording', 'Recording fees', 'gov', null],
    ['hcTransfer', 'Transfer taxes', 'gov', 'price'],
    ['hcInspection', 'Home inspection', 'other', null],
    ['hcSurvey', 'Survey', 'other', null],
    ['hcPest', 'Pest inspection', 'other', null],
    ['hcHoaTransfer', 'HOA transfer fee', 'other', null],
    ['hcOther', 'Other costs', 'other', null]
  ];
  var GROUPS = { lender: 'Lender fees', title: 'Title and settlement', gov: 'Government fees', other: 'Other services' };

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }

  function read(id, blank) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blank;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function unit(id) { var u = el(id + 'Unit'); return u ? u.value : 'dollar'; }
  function amount(v, u, base) { return u === 'percent' ? base * v / 100 : v; }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  function clear() {
    ['hcCashToClose', 'hcClosingCosts', 'hcPrepaids', 'hcClosingPct', 'hcLoan', 'hcDownOut', 'hcLenderTotal',
     'hcTitleTotal', 'hcGovTotal', 'hcOtherTotal', 'hcPrepaidInterest', 'hcPrepaidIns', 'hcEscrowTotal',
     'hcCreditsOut', 'hcMonthly'].forEach(function (id) { setText(id, '–'); });
    setText('hcDownHint', '');
    el('hcItems').innerHTML = '';
    el('hcNote').hidden = true;
  }

  function update() {
    var price = read('hcPrice', NaN), down = read('hcDown', 0), rate = read('hcRate', 0), years = read('hcTerm', NaN);
    var err = el('hcError'), msg = '';
    var downAmt = amount(down, unit('hcDown'), price);
    var vals = [], items = [];
    ITEMS.forEach(function (it) {
      var v = read(it[0], 0);
      vals.push(v);
      items.push({ label: it[1], group: it[2], value: v, unit: it[3] ? unit(it[0]) : 'dollar', base: it[3] });
    });
    var tax = read('hcPropTax', 0), ins = read('hcInsurance', 0), insMonths = read('hcInsMonths', 0),
        taxEscrow = read('hcTaxEscrow', 0), insEscrow = read('hcInsEscrow', 0), days = read('hcDays', 0),
        earnest = read('hcEarnest', 0), seller = read('hcSellerCredit', 0), lenderCredit = read('hcLenderCredit', 0);
    var others = [down, rate, tax, ins, insMonths, taxEscrow, insEscrow, days, earnest, seller, lenderCredit].concat(vals);
    if (isNaN(price) || isNaN(years) || others.some(isNaN)) msg = 'Fill in the price and loan term, and use numbers only.';
    else if (price <= 0 || price > 1e10) msg = 'Enter a home price above $0.';
    else if (others.some(function (v) { return v < 0 || v > 1e10; })) msg = 'Amounts and rates can\'t be negative.';
    else if (downAmt > price) msg = 'The down payment can\'t be more than the price.';
    else if (rate > 30) msg = 'Enter an interest rate of 30% or less.';
    else if (years < 1 || years > 50) msg = 'Enter a loan term of 1 to 50 years.';
    else if (insMonths > 24 || taxEscrow > 24 || insEscrow > 24 || days > 366) msg = 'Enter up to 24 months of prepaid or escrowed costs and up to 366 days of interest.';
    else if (items.some(function (it) { return it.unit === 'percent' && it.value > 100; }) || (unit('hcPropTax') === 'percent' && tax > 100)) msg = 'Percentages can\'t be above 100%.';
    err.hidden = !msg;
    if (msg) { err.textContent = msg; clear(); return; }

    var loan = Math.max(0, price - downAmt);
    var totals = { lender: 0, title: 0, gov: 0, other: 0 };
    items.forEach(function (it) {
      it.amount = amount(it.value, it.unit, it.base === 'loan' ? loan : price);
      totals[it.group] += it.amount;
    });
    var closing = totals.lender + totals.title + totals.gov + totals.other;
    var annualTax = amount(tax, unit('hcPropTax'), price);
    var prepaidInterest = loan * rate / 100 / 365 * days;
    var prepaidIns = ins * insMonths / 12;
    var escrowTax = annualTax / 12 * taxEscrow, escrowIns = ins / 12 * insEscrow;
    var prepaids = prepaidInterest + prepaidIns + escrowTax + escrowIns;
    var credits = Math.min(seller + lenderCredit, closing + prepaids);
    var cash = downAmt + closing + prepaids - credits - earnest;

    setText('hcCashToClose', money.format(cash));
    setText('hcClosingCosts', money.format(closing));
    setText('hcPrepaids', money.format(prepaids));
    setText('hcClosingPct', pct.format(closing / price));
    setText('hcLoan', money.format(loan));
    setText('hcDownOut', money.format(downAmt));
    setText('hcDownHint', unit('hcDown') === 'percent' ? money.format(downAmt) + ' down' : pct.format(downAmt / price) + ' of the price');
    setText('hcLenderTotal', money.format(totals.lender));
    setText('hcTitleTotal', money.format(totals.title));
    setText('hcGovTotal', money.format(totals.gov));
    setText('hcOtherTotal', money.format(totals.other));
    setText('hcPrepaidInterest', money.format(prepaidInterest));
    setText('hcPrepaidIns', money.format(prepaidIns));
    setText('hcEscrowTotal', money.format(escrowTax + escrowIns));
    setText('hcCreditsOut', '−' + money.format(credits + earnest));
    var pi = monthlyPayment(loan, rate / 100, Math.round(years * 12));
    setText('hcMonthly', money.format(pi + annualTax / 12 + ins / 12));

    var rows = [];
    ['lender', 'title', 'gov', 'other'].forEach(function (g) {
      items.forEach(function (it) {
        if (it.group === g && it.amount > 0) rows.push([GROUPS[g], it.label, it.amount]);
      });
    });
    if (prepaidInterest > 0) rows.push(['Prepaids', 'Prepaid interest (' + days + (days === 1 ? ' day)' : ' days)'), prepaidInterest]);
    if (prepaidIns > 0) rows.push(['Prepaids', 'Homeowners insurance (' + insMonths + ' months)', prepaidIns]);
    if (escrowTax > 0) rows.push(['Escrow deposit', 'Property tax (' + taxEscrow + ' months)', escrowTax]);
    if (escrowIns > 0) rows.push(['Escrow deposit', 'Homeowners insurance (' + insEscrow + ' months)', escrowIns]);
    var html = rows.map(function (r) {
      return '<tr><td>' + r[0] + '</td><td>' + r[1] + '</td><td>' + money.format(r[2]) + '</td></tr>';
    });
    html.push('<tr><td></td><td><strong>Total closing costs, prepaids and escrow</strong></td><td><strong>' + money.format(closing + prepaids) + '</strong></td></tr>');
    el('hcItems').innerHTML = html.join('');

    var note = el('hcNote'), text = '';
    if (seller + lenderCredit > closing + prepaids) text = 'Your credits are larger than your closing costs. Lenders generally won\'t let credits pay toward the down payment, so only ' + money.format(credits) + ' is counted.';
    else if (cash < 0) text = 'Your earnest money and credits exceed what is due, so you would get money back at closing.';
    note.hidden = !text;
    note.textContent = text;
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('hcForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
